/*
  "ag impact", written as one monoline pen centreline (generated offline, do not edit by hand).

  Source: the letterforms are the stroke paths of "Hershey Script 1-stroke" (the Hershey fonts, as
  shipped in SVG form with Inkscape's Hershey Text extension, svg_fonts/HersheyScript1.svg). The
  Hershey fonts were originally created by Dr. A. V. Hershey while working at the U. S. National
  Bureau of Standards. The format of the font data in that distribution was originally created by
  James Hurt, Cognition, Inc., 900 Technology Park Drive, Billerica, MA 01821. Free for any use,
  commercial or otherwise, with this acknowledgement.

  How it was derived: glyph centrelines a, g, i, m, p, a, c, t laid out with the font's advances;
  letters joined into pen strokes (a, g and c are entered from the previous letter's exit up their
  left side and over the top, then turn at the stem, the way a school hand writes them; the p bowl
  closes with a short retrace); pieces between pen reversals smoothed (Chaikin x5, even resampling,
  Laplacian passes); the i lead-in lengthened, the p descender shortened a little, the t-cross
  tilted, the slant eased by 6 degrees (rounder and more upright, closer to Apple's hello); then
  normalised to a width of 1000 units and resampled every 2 units. The generator script is
  not part of the repo.

  Units: x right, y down. `baseline` and `xHeight` are in the same units. Points are flat
  [x0, y0, x1, y1, ...]; `cusps` are point indices where the pen reverses (a retrace or a sharp
  turn). Strokes are in writing order: "ag", "impact", then the t-cross and the i-dot.
*/

export type PenStroke = {
  name: string;
  /** Point indices where the pen reverses direction. */
  cusps: readonly number[];
  /** Flat x, y pairs along the pen path, every 2 units. */
  points: readonly number[];
};

export type PenSignature = {
  width: number;
  height: number;
  baseline: number;
  xHeight: number;
  /** Pen width the letters were designed with, in the same units. */
  stroke: number;
  strokes: readonly PenStroke[];
};

